import sys
from collections import defaultdict

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    MOD = 10**9 + 7

    parent = list(range(m + 1))

    def find(i):
        path = []
        while parent[i] != i:
            path.append(i)
            i = parent[i]
        for node in path:
            parent[node] = i
        return i

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    selected_indices = []
    basis_count = 0

    for idx in range(1, n + 1):
        try:
            k = int(next(iterator))
            coords = []
            for _ in range(k):
                coords.append(int(next(iterator)))
        except StopIteration:
            break

        if k == 1:
            u = coords[0]
            root_u = find(u)
            if root_u != u:
                union(root_u, u)
                basis_count += 1
                selected_indices.append(idx)
            else:
                pass
        else:
            u, v = coords[0], coords[1]
            root_u = find(u)
            root_v = find(v)

            if root_u != root_v:
                union(root_u, root_v)
                basis_count += 1
                selected_indices.append(idx)

    num_components = 0
    for i in range(1, m + 1):
        if parent[i] == i:
            num_components += 1

    size_t = pow(2, num_components, MOD)

    print(f"{size_t} {len(selected_indices)}")
    print(" ".join(map(str, sorted(selected_indices))))

if __name__ == "__main__":
    solve()
